INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16501, 'Ecclesiastes 9:16', 'Ecclesiastes', 9, 16, '&nbsp;نو زۀ وايم چې حِکمت د طاقت نه ښۀ دے، خو د غريب سړى هوښيارتيا ته سپک کتلے شى، هيڅوک د هغۀ خبرو ته پام نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16502, 'Ecclesiastes 9:17', 'Ecclesiastes', 9, 17, '&nbsp;ښۀ خبره دا ده چې د يو هوښيار کس په مزه خبرو ته غوږ ونيسې په ځائ د دې نه چې د کم عقلانو په مجلس کښې د بادشاه چغې واورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16503, 'Ecclesiastes 9:18', 'Ecclesiastes', 9, 18, '&nbsp;حِکمت د جنګ د وسلو نه طاقتور دے، خو يو ګناهګار کس ډېر زيات ښۀ کارونه تباه کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16504, 'Ecclesiastes 10:1', 'Ecclesiastes', 10, 1, '&nbsp;څنګه چې مړۀ مچان خوشبودار عطر خرابوى نو داسې لږ شان کم عقلتوب ډېر حِکمت او عزت خرابولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16505, 'Ecclesiastes 10:2', 'Ecclesiastes', 10, 2, '&nbsp;د هوښيار سړى زړۀ به صحيح لار غوره کوى او د کم عقل سړى زړۀ به خرابه لار غوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16506, 'Ecclesiastes 10:3', 'Ecclesiastes', 10, 3, '&nbsp;کله هم چې کم عقل په لاره روان وى نو صفا پته لګى چې هغه بې‌وقوف دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16507, 'Ecclesiastes 10:4', 'Ecclesiastes', 10, 4, '&nbsp;کۀ حکمران درته غصه شى نو خپل ځائ مۀ پرېږده، ځکه چې ستا سړه رويه د هغۀ سخته غصه قلارولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16508, 'Ecclesiastes 10:5', 'Ecclesiastes', 10, 5, '&nbsp;ما په مخ د زمکې يو بل خراب څيز ليدلے دے او دا غلطى د حکمرانانو د لاسه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16509, 'Ecclesiastes 10:6', 'Ecclesiastes', 10, 6, '&nbsp;او هغه دا چې کم عقل خلق په اوچتو عُهدو مقرر کړے شى او مالدار خلق په معمولى عُهدو باندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16510, 'Ecclesiastes 10:7', 'Ecclesiastes', 10, 7, '&nbsp;ما ليدلى دى چې غلامان د شهزادګانو په شان په آسونو سوارۀ وى، او شهزادګان د نوکرانو په شان پېدل ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16511, 'Ecclesiastes 10:8', 'Ecclesiastes', 10, 8, '&nbsp;څوک چې کنده کنى کېدے شى په خپله وروغورزيږى، څوک چې دېوال راغورزوى کېدے شى مار يې وچيچى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16512, 'Ecclesiastes 10:9', 'Ecclesiastes', 10, 9, '&nbsp;څوک چې د کاڼو په کان کښې کار کوى، کېدے شى په کاڼو چخڼى شى. څوک چې لرګى ماتوى، نو کېدے شى چې په دې زخمى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16513, 'Ecclesiastes 10:10', 'Ecclesiastes', 10, 10, '&nbsp;کۀ تبر پڅ وى او تېرۀ يې نۀ کړې، نو په دې باندې کار کول ډېر زور غواړى. خو حِکمت سړے همېشه د کاميابۍ طرف ته بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16514, 'Ecclesiastes 10:11', 'Ecclesiastes', 10, 11, '&nbsp;کۀ د دم نه مخکښې مار پاړو وچيچى نو بيا د پاړوتوب څۀ فائده نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16515, 'Ecclesiastes 10:12', 'Ecclesiastes', 10, 12, '&nbsp;د هوښيار سړى خبرې د هغۀ د عزت سبب جوړيږى، خو د کم عقل سړى خبرې د هغۀ د تباهۍ سبب جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16516, 'Ecclesiastes 10:13', 'Ecclesiastes', 10, 13, '&nbsp;د هغوئ خبرې کم عقلتوب سره شروع کيږى او خطرناک ليونتوب سره تر سره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16517, 'Ecclesiastes 10:14', 'Ecclesiastes', 10, 14, '&nbsp;د کم عقل کس خبرې نۀ ختميږى. هيچا ته دا پته نشته چې په راتلونکى وخت کښې به څۀ کيږى، څوک دا وئيلے شى چې زمونږ د مرګ نه پس به څۀ کيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16518, 'Ecclesiastes 10:15', 'Ecclesiastes', 10, 15, '&nbsp;کار سره کم عقل ډېر ستړے شى، او هغۀ ته دا پته هم نۀ لګى چې منزل ته خپله لار پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16519, 'Ecclesiastes 10:16', 'Ecclesiastes', 10, 16, '&nbsp;افسوس په هغه مُلک چې د هغې بادشاه يو ناتجربه‌کاره زلمے وى او مشران يې سم د سحر نه سر د خېټې نه زار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16520, 'Ecclesiastes 10:17', 'Ecclesiastes', 10, 17, '&nbsp;خوش قسمته وى هغه مُلک چې د چا بادشاه چې د شريف خاندان نه وى او د هغوئ مشران په مناسب وخت خوراک کوى. هغوئ د طاقت حاصلولو دپاره خوراک څښاک کوى د نشې دپاره نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16521, 'Ecclesiastes 10:18', 'Ecclesiastes', 10, 18, '&nbsp;کۀ يو کس دومره ناراسته وى چې هغه خپل چت هم نۀ مرمت کوى، نو دا به راڅاڅى او هغه کور به راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16522, 'Ecclesiastes 10:19', 'Ecclesiastes', 10, 19, '&nbsp;د مېلمستيا روټۍ د خوشحالۍ دپاره وى او مے د زړۀ راحت دپاره وى، او په پېسو هر کار کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16523, 'Ecclesiastes 10:20', 'Ecclesiastes', 10, 20, '&nbsp;په خيالونو کښې هم په بادشاه پسې بدرد مۀ وايه او په خپله کوټه کښې هم په مالداره کس پسې بدرد مۀ وايه. کېدے شى چې د هوا يوه وړه مرغۍ ستا خبرې واورى او هغۀ ته يې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16524, 'Ecclesiastes 11:1', 'Ecclesiastes', 11, 1, '&nbsp;خپله روټۍ په اوبو باندې وغورزوه چې لاړه شى او ډيرې ورځې پس به دا تا ته بيا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16525, 'Ecclesiastes 11:2', 'Ecclesiastes', 11, 2, '&nbsp;خپلې پېسې په اووۀ يا اتۀ ځايونو کښې بندې کړه، ځکه چې هيڅ پته نۀ لګى چې څۀ افت به په زمکه باندې راپېښ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16526, 'Ecclesiastes 11:3', 'Ecclesiastes', 11, 3, '&nbsp;کله چې وريځې درنې وى نو باران کيږى. کله چې ونه د شمال يا د جنوب په طرف پرېوځى نو هم هلته پرته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16527, 'Ecclesiastes 11:4', 'Ecclesiastes', 11, 4, '&nbsp;هغه زميدار څوک چې د هوا رخ ته ګورى هغه به خپل فصل نۀ کَرى. او هغه زميدار څوک چې وريځو ته ګورى هغه به خپل فصل نۀ رېبى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16528, 'Ecclesiastes 11:5', 'Ecclesiastes', 11, 5, '&nbsp;لکه څنګه چې تا ته د هوا رخ نۀ معلوميږى او نۀ درته دا پته لګى چې د مور په خېټه کښې ماشوم څنګه جوړيږى، نو داسې تۀ د خُدائ پاک په کارونو هم نۀ پوهېږې، څوک چې د هر څۀ خالق دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16529, 'Ecclesiastes 11:6', 'Ecclesiastes', 11, 6, '&nbsp;د سحر په وخت خپل تخم کره او تر ماښامه پورې په کار کښې بوخت اوسه، ځکه چې تا ته څۀ پته ده چې په کوم کار کښې کاميابې ده، په دې کښې، په هغې کښې او يا په دواړو کښې يو شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16530, 'Ecclesiastes 11:7', 'Ecclesiastes', 11, 7, '&nbsp;رڼا ښۀ ده او د نوى سحر رڼا په سترګو ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16531, 'Ecclesiastes 11:8', 'Ecclesiastes', 11, 8, '&nbsp;کله چې انسان تر ډېر وخته پورې ژوندے پاتې شى نو هغوئ دې د ژوند هره لحظه خوشحاله تېروى. خو دا هم ياد ساتل پکار دى چې د مشکل ډيرې ورځې راروانې دى. او څۀ چې به کيږى هغه يو راز دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16532, 'Ecclesiastes 11:9', 'Ecclesiastes', 11, 9, '&nbsp;اے ځوانانو، په خپله ځوانۍ خوشحاله اوسئ او د ځوانۍ نه خوند اخلئ. او څۀ چې ستاسو زړۀ غواړئ او په سترګو مو ښۀ لګى نو هغه کوئ، خو دا خبره ياده ساتئ چې خُدائ پاک به درسره د هر کار او عمل حِساب کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16533, 'Ecclesiastes 11:10', 'Ecclesiastes', 11, 10, '&nbsp;د خپل زړۀ نه خفګان او د وجود نه غم درد لرې ساتئ ځکه چې ځوانى او تور سر د يوې لحظې دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16534, 'Ecclesiastes 12:1', 'Ecclesiastes', 12, 1, '&nbsp;هم په ځوانۍ کښې خپل خالِق ياد ساته، د هغې نه مخکښې چې د مصيبت ورځې راشى، او هغه کلونه راشى او تۀ پکښې ووائې چې، ”د ژوند هيڅ مزه نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16535, 'Ecclesiastes 12:2', 'Ecclesiastes', 12, 2, '&nbsp;هغه ياد ساته، د دې نه مخکښې چې د نمر، سپوږمۍ او د ستورو رڼا تا ته تته ښکاره شى او د باران نه پس بيا وريځې راواپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16536, 'Ecclesiastes 12:3', 'Ecclesiastes', 12, 3, '&nbsp;د هغې نه مخکښې چې ستا د کور څوکيداران په ريږدېدو شى، او ستا طاقتور سړى راکونټى شى، او ستا د مېچنې کولو والا ښځې کار پرېږدى ولې چې هغوئ لږې دى، او هغه زنانه چې د کړکو نه ګورې د هغوئ نظر کم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16537, 'Ecclesiastes 12:4', 'Ecclesiastes', 12, 4, '&nbsp;د هغې نه مخکښې چې د کوڅې دروازې بندې شى او د مېچنې آواز په مزه شى، او تۀ د مارغانو په اولنو سندرو راپاڅې خو بيا د هغوئ ټولې سندرې په تا په مزه لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16538, 'Ecclesiastes 12:5', 'Ecclesiastes', 12, 5, '&nbsp;د هغې نه مخکښې چې تۀ د اوچتو ځايونو او د کوڅو د خطرو نه يرېږې. د هغې نه مخکښې چې ستا وېښتۀ سپين شى داسې لکه چې د بادامو ګلونه کولاو شى، او تۀ د پښو نه پاتې شې داسې لکه مُلخ پښې راکاږى، او ستا شهوت ختم شى. هغه ياد ساته، د هغې نه مخکښې چې ستا پښې په قبر کښې وى کوم چې به ستا ابدى کور وى، او کله به چې خلق ستا په جنازه کښې وير کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16539, 'Ecclesiastes 12:6', 'Ecclesiastes', 12, 6, '&nbsp;د هغې نه مخکښې چې د سپينو زرو زنځير وشليږى، د سرو زرو لوښے ټوټې ټوټې شى، او چينې سره د اوبو بوقه به وشليږى او د کوهى سَرخۍ ماته شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16540, 'Ecclesiastes 12:7', 'Ecclesiastes', 12, 7, '&nbsp;بيا به خاوره واپس خاورې شى او روح به خُدائ پاک له واپس لاړ شى، چا چې هغه ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16541, 'Ecclesiastes 12:8', 'Ecclesiastes', 12, 8, '&nbsp;نو معلِم وائى، ”هر څۀ بې‌معنې دى، دا هر څۀ بې‌معنې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16542, 'Ecclesiastes 12:9', 'Ecclesiastes', 12, 9, '&nbsp;معلِم په خپله هوښيار وو او خلقو له يې هم د عِلم تعليم ورکولو. هغۀ په ډېرو متلونو باندې غور او فکر کولو او ترتيب وار يې جمع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16543, 'Ecclesiastes 12:10', 'Ecclesiastes', 12, 10, '&nbsp;د معلِم کوشش دا وو چې خوږې خبرې ولټوى، او ديانتدارۍ سره رښتينى خبرې وليکى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16544, 'Ecclesiastes 12:11', 'Ecclesiastes', 12, 11, '&nbsp;د هوښيارانو خبرې د تېرو چُوکو په شان دى، د جمع شوى متلونو خبرې د چُوکو په څوکه کښې د مېخونو په شان دى چې يو شپون يې د ګډو د بوتلو دپاره استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16545, 'Ecclesiastes 12:12', 'Ecclesiastes', 12, 12, '&nbsp;خو زما زويه، د دې نه علاوه هم خبردار اوسه. د ډېرو کتابونو د ليکلو سلسله به هيڅکله نۀ ختميږى او ډېره مطالعه وجود ستړے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16546, 'Ecclesiastes 12:13', 'Ecclesiastes', 12, 13, '&nbsp;راځئ چې اوس په آخر کښې د ټول تعليم په خُلاصه باندې غور وکړُو. د خُدائ پاک نه يرېږه او د هغۀ په حُکمونو عمل کوه، دا په هر انسان فرض دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16547, 'Ecclesiastes 12:14', 'Ecclesiastes', 12, 14, '&nbsp;ځکه چې خُدائ پاک به راسره د هر يو عمل عدالت کوى، کۀ هغه ښۀ وى او کۀ بد او په دې کښې پټ څيزونه هم شامل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16548, 'Isaiah 1:1', 'Isaiah', 1, 1, '&nbsp;په دې کِتاب کښې د يهوداه او د يروشلم په حقله هغه پېغامونه دى کوم چې خُدائ پاک د آموص زوئ يشعياه باندې په هغه وخت کښې څرګند کړل کله چې عُزياه، يوتام، احاز او حزقياه د يهوداه بادشاهان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16549, 'Isaiah 1:2', 'Isaiah', 1, 2, '&nbsp;مالِک خُدائ وفرمائيل، ”اے زمکې او آسمانه، زۀ چې څۀ وايم نو هغه واورئ. ما چې د کومو بچو پالنه کړې ده او خيال مې ساتلے دے نو هغوئ زما خِلاف بغاوت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16550, 'Isaiah 1:3', 'Isaiah', 1, 3, '&nbsp;غوَيے خپل مالِک پېژنى او خر د خپل مالِک اخور پېژنى. خو بنى اِسرائيل خپل مالِک نۀ پېژنى، زما خلق د عقل نه خلاص دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16551, 'Isaiah 1:4', 'Isaiah', 1, 4, '&nbsp;اے ګناهګار قومه، تاسو خپلو ګناهونو رالاندې کړى يئ. بدعمله نسله، بدکرداره بچو، تاسو خپل مالِک خُدائ رد کړے دے. کوم چې د بنى اِسرائيلو مقدس خُدائ پاک دے او تاسو د هغۀ نه مخ اړولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16552, 'Isaiah 1:5', 'Isaiah', 1, 5, '&nbsp;تاسو خپله سرکشى ولې نۀ پرېږدئ؟ تاسو غواړئ چې نوره سزا هم درته مِلاو شى؟ ستاسو سرونه په زخمونو باندې پټ دى او ستاسو زړونه بيمار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16553, 'Isaiah 1:6', 'Isaiah', 1, 6, '&nbsp;د سر نه واخله تر پښو پورې ستاسو په بدن کښې يو ځائ هم روغ نشته. تاسو ټول ټکېدلى يئ، زخمى يئ او تغمې درباندې ولاړې دى. نۀ ستاسو زخمونه صفا کړے شوى دى، او نۀ ورباندې مرهم پټۍ شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16554, 'Isaiah 1:7', 'Isaiah', 1, 7, '&nbsp;ستاسو مُلک شاړ شوے دے، ستاسو ښارونه سوزولے شوى دى. ستاسو په وړاندې د پردى مُلک خلق ستاسو پټى لوټ کوى، او هر څۀ چې وينى هغه تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16555, 'Isaiah 1:8', 'Isaiah', 1, 8, '&nbsp;صرف صيون لور باقى پاتې ده، لکه چې د انګورو په باغ کښې د څوکيدار جومپړۍ پاتې وى يا د بادرنګو په پټى کښې يو څپر بې‌اسرى وى، او د محاصرې لاندې بې‌اسرى ښار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16556, 'Isaiah 1:9', 'Isaiah', 1, 9, '&nbsp;کۀ مالِک خُدائ ربُ الافواج يو څو کسان ژوندى نۀ وے پرېښے، نو يروشلم به د سدوم او عموره په شان تباه شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16557, 'Isaiah 1:10', 'Isaiah', 1, 10, '&nbsp;اے يروشلمه، ستا حکمرانان او ستا خلق د سدوم او د عموره په شان دى. چې مالِک خُدائ درته څۀ فرمائى نو هغې ته غوږ ونيسه او چې خُدائ پاک درته څۀ ښودنه کوى نو هغې ته توجو وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16558, 'Isaiah 1:11', 'Isaiah', 1, 11, '&nbsp;مالِک خُدائ فرمائى، ”کۀ تاسو بې‌شمېره قربانيانې پېش کړئ نو زما پرې څۀ؟ زۀ د ښو ځناورو وازګې او د ګډانو د سوزېدونکو قربانو نه پوزې له راغلے يم. په دې زۀ نۀ خوشحالېږم چې تاسو ما ته د غوَيانو، ګډو او د چېلو وينې پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16559, 'Isaiah 1:12', 'Isaiah', 1, 12, '&nbsp;کله چې تاسو زما حضور ته راځئ نو ولې ستاسو خيال دا دے څۀ چې زۀ دا غواړم چې ستاسو ځناور دې زما په دربار کښې ګرځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16560, 'Isaiah 1:13', 'Isaiah', 1, 13, '&nbsp;تاسو چې ما له کومې نذرانې راوړئ دا بې‌فائدې دى. تاسو چې د خوشبويۍ کومې مصالحې سوزوئ نو د هغې نه زۀ نفرت کوم. زۀ ستاسو د نوې مياشتې اخترونه، ستاسو د سبت ورځې او ستاسو مذهبى اجتماعګانې نۀ شم برداشت کولے، دا هر څۀ ستاسو د ګناهونو په وجه خراب شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16561, 'Isaiah 1:14', 'Isaiah', 1, 14, '&nbsp;ستاسو د نوې مياشتې د اخترونو او ستاسو د مقدسو ورځو نه زۀ نفرت کوم، دا په ما باندې يو بوج جوړ شوے دے او د دې برداشت کولو نه زۀ تنګ راغلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16562, 'Isaiah 1:15', 'Isaiah', 1, 15, '&nbsp;کله چې تاسو د دُعا دپاره لاسونه پورته کړئ، نو زۀ به ستاسو نه مخ واړوم. تاسو چې هر څومره دُعاګانې وکړئ، نو زۀ به يې نۀ قبلوم، ځکه چې ستاسو لاسونه په وينو رنګ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16563, 'Isaiah 1:16', 'Isaiah', 1, 16, '&nbsp;اول ولامبئ او خپل ځان صفا کړئ. خپلې بد عملى زما د سترګو نه لرې کړئ. آو، نور بد عمل مۀ کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16564, 'Isaiah 1:17', 'Isaiah', 1, 17, '&nbsp;نېکى کول زده کړئ. او ګورئ چې اِنصاف کيږى، د چا سره چې ظلم شوے وى د هغوئ مدد کوئ، يتيمانانو له خپل حقُونه ورکوئ او د کونډو د حق دِفاع کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16565, 'Isaiah 1:18', 'Isaiah', 1, 18, '&nbsp;مالِک خُدائ فرمائى، ”راځئ چې اوس دا مسئله حل کړُو. اګر چې ستاسو ګناهونو تاسو تک سرۀ داغى کړى يئ، خو زۀ به تاسو صفا کړم او لکه د واورې په شان به مو سپين کړم، اګر چې ستاسو داغونه تک سرۀ دى، خو تاسو به د وړۍ په شان تک سپين شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16566, 'Isaiah 1:19', 'Isaiah', 1, 19, '&nbsp;خو کۀ تاسو خپلې رضا سره تابعدار يئ، نو چې زمکه کوم ښۀ څيزونه پېدا کوى، هغه به تاسو خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16567, 'Isaiah 1:20', 'Isaiah', 1, 20, '&nbsp;خو کۀ تاسو اِنکار او سرکشى کوئ، نو د تُورې لاندې به ګېر شئ او مړۀ به شئ. دا د مالِک خُدائ د خولې کلام دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16568, 'Isaiah 1:21', 'Isaiah', 1, 21, '&nbsp;هغه ښار چې په يو وخت کښې وفادار وو اوس د کنجرې په شان شوے دے. په يوه زمانه کښې دا د صداقت او اِنصاف نه ډک وو، خو اوس په کښې صرف قاتِلان پاتې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16569, 'Isaiah 1:22', 'Isaiah', 1, 22, '&nbsp;اے يروشلمه، ستا خالص سپين زر اوس د ملاوټ نه ډک دى، او ستا بهترينو ميو کښې اوبۀ ګډې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16570, 'Isaiah 1:23', 'Isaiah', 1, 23, '&nbsp;ستا مشران باغيان شوى دى او د غلو ملګرى شوى دى، هغوئ هر وخت تُحفې او رشوتونه اخلى. هغوئ په عدالت کښې هيڅکله د يتيمانانو دفاع نۀ کوى او نۀ هغوئ ته د کونډو فرياد را رسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16571, 'Isaiah 1:24', 'Isaiah', 1, 24, '&nbsp;نو هغې ته غوږ ونيسئ څۀ چې مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ تعالىٰ فرمائى، ”زۀ به خپلو دشمنانو نه انتقام واخلم، او مخالفينو نه به بدل واخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16572, 'Isaiah 1:25', 'Isaiah', 1, 25, '&nbsp;زۀ به ستاسو خِلاف خپل طاقت استعمال کړم. زۀ به تاسو داسې صفا کړم لکه څنګه چې اوسپنه په اور کښې صفا کيږى او زۀ به ستاسو نه ټول ملاوټ لرې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16573, 'Isaiah 1:26', 'Isaiah', 1, 26, '&nbsp;زۀ به تا له هغه شان قاضيان او مشيران درکړم لکه څنګه چې دې پخوا لرل. نو بيا به يروشلم د صادقانو او وفادارو خلقو ښار وبللے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16574, 'Isaiah 1:27', 'Isaiah', 1, 27, '&nbsp;مالِک خُدائ به اِنصاف سره يروشلم بيا آباد کړى او چې څوک هلته توبه وباسى هغه به بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16575, 'Isaiah 1:28', 'Isaiah', 1, 28, '&nbsp;خو مالِک خُدائ به هغه هر يو کس ريزې ريزې کړى څوک چې ګناه کوى او د هغۀ خِلاف بغاوت کوى، او څوک چې مالِک خُدائ ته شا کړى نو هغه به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16576, 'Isaiah 1:29', 'Isaiah', 1, 29, '&nbsp;د څېړۍ د مقدسو ونو عبادت سره به چې تاسو خوشحالېدئ نو د هغې په وجه به تاسو وشرمېږئ، او کوم باغونه چې تاسو د بُت پرستۍ دپاره غوره کړى دى نو د هغې په وجه به تاسو وشرمېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16577, 'Isaiah 1:30', 'Isaiah', 1, 30, '&nbsp;تاسو به د څېړۍ د داسې ونې په شان يئ چې پاڼې يې اوچې شوى وى او د يو داسې باغ په شان به يئ چې هيڅ اوبۀ په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16578, 'Isaiah 1:31', 'Isaiah', 1, 31, '&nbsp;نو هغه تکړه سړى به لکه د بوسو په شان وى او د هغوئ بد عملونه به د اور د بڅرکى په شان وى. دواړه به يو ځائ داسې اور واخلى چې هيڅ څوک به يې مړ کولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16579, 'Isaiah 2:1', 'Isaiah', 2, 1, '&nbsp;دا هغه پېغام دے چې خُدائ پاک د آموص زوئ يشعياه باندې د يهوداه او يروشلم په حقله نازل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16580, 'Isaiah 2:2', 'Isaiah', 2, 2, '&nbsp;په راتلونکى وخت کښې، په کوم غرۀ باندې چې د مالِک خُدائ کور جوړ دے، هغه به د ټولو نه اوچت غر وى، د غرونو په ټولو غونډو باندې به دا د برج په شان اوچت وى. او ټول قومونه به د سېلاب په شان ور روان وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16581, 'Isaiah 2:3', 'Isaiah', 2, 3, '&nbsp;او د ډېرو قومونو خلق به راشى او وبه وائى، ”راځئ چې د مالِک خُدائ غر ته وخېژُو، او چې د بنى اِسرائيلو د خُدائ پاک کور ته لاړ شُو، هلته به هغه مونږ ته خپلې لارې وښائى، او مونږ به د هغۀ په لارو ځو.“ ځکه چې د صيون نه به د هغۀ تعليمات راوځى، او د هغۀ کلام به د يروشلم نه راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16582, 'Isaiah 2:4', 'Isaiah', 2, 4, '&nbsp;مالِک خُدائ به د قومونو اِنصاف وکړى او د هغوئ په مينځ کښې به لانجې هوارې کړى. هغوئ به د خپلو تُورو نه د يوې خولې جوړې کړى او د خپلو نېزو نه به د بوټو قينچيانې جوړې کړى. قومونه به هيڅکله بيا جنګ له لاړ نۀ شى، او نۀ به بيا دوئ د جنګ تربيت حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16583, 'Isaiah 2:5', 'Isaiah', 2, 5, '&nbsp;نو اے د يعقوب اولاده، راځئ چې مونږ د مالِک خُدائ په رڼا کښې ګرځو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16584, 'Isaiah 2:6', 'Isaiah', 2, 6, '&nbsp;اے مالِکه خُدايه، تا خپل خلق، د يعقوب اولاد رد کړے دے. ځکه چې هغوئ خپل مُلک د نمرخاتۀ د طرف د جادوګرۍ نه ډک کړے دے. د فلستيانو په شان هغوئ هم فالګرو له ځى او د بل مُلک خلقو سره غاړه غټۍ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16585, 'Isaiah 2:7', 'Isaiah', 2, 7, '&nbsp;د هغوئ مُلک د سپينو زرو او سرو زرو نه ډک دے او د هغوئ خزانې نۀ ختميږى. د هغوئ مُلک د آسونو نه ډک دے او د هغوئ جنګى ګاډۍ بې‌شمېره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16586, 'Isaiah 2:8', 'Isaiah', 2, 8, '&nbsp;د هغوئ مُلک د بُتانو نه ډک دے او هغوئ داسې څيزونو ته سجدې لګوى چې هغوئ په خپلو لاسونو جوړ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16587, 'Isaiah 2:9', 'Isaiah', 2, 9, '&nbsp;نو په دې وجه به هغوئ بې‌عزته او سپک شى. اے مالِکه خُدايه، هغوئ مۀ معاف کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16588, 'Isaiah 2:10', 'Isaiah', 2, 10, '&nbsp;په غارونو کښې ورننوځئ او د مالِک خُدائ د يرې نه او د هغۀ د شان او شوکت نه ځان په خاورو کښې پټ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16589, 'Isaiah 2:11', 'Isaiah', 2, 11, '&nbsp;د انسان مغروره سترګې به ټيټې کړے شى او د انسان لوئى به په عاجزۍ بدله شى. نو په هغه ورځ به صرف د مالِک خُدائ ثناء صِفت کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16590, 'Isaiah 2:12', 'Isaiah', 2, 12, '&nbsp;په هغه ورځ به مالِک خُدائ ربُ الافواج ټول طاقتور خلق او هغه هر څوک چې مغروره يا لوئ وى، هغه ټول به عاجزه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16591, 'Isaiah 2:13', 'Isaiah', 2, 13, '&nbsp;هغه به د لبنان لوړ لوړ دِيار او د بسن د مُلک د څېړۍ ټولې ونې تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16592, 'Isaiah 2:14', 'Isaiah', 2, 14, '&nbsp;هغه به اوچت غرونه او د غرونو اوچتې غونډۍ هوارې کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16593, 'Isaiah 2:15', 'Isaiah', 2, 15, '&nbsp;هغه به هر يو اوچت برج او د هرې قلعې مضبوط دېوالونه هوار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16594, 'Isaiah 2:16', 'Isaiah', 2, 16, '&nbsp;هغه به ټول لوئ سمندرى جهازُونه او ټولې ښائسته کشتۍ ډوبې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16595, 'Isaiah 2:19', 'Isaiah', 2, 19, '&nbsp;چې کله مالِک خُدائ د دُنيا يرولو دپاره پاڅى نو خلق به د غرونو په غارونو کښې پټيږى او په زمکه کښې به په سوړو کښې پټيږى، د دې دپاره چې د مالِک خُدائ د دهشت او جلال نه وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16596, 'Isaiah 2:20', 'Isaiah', 2, 20, '&nbsp;کله چې هغه ورځ راشى، نو هغوئ چې کوم د سپينو زرو او سرو زرو بُتان جوړ کړى وى چې عبادت يې وکړى نو هغه به وغورزوى. او هغوئ به منږکانو او ښاپېرکانو ته پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16597, 'Isaiah 2:21', 'Isaiah', 2, 21, '&nbsp;چې کله مالِک خُدائ د دُنيا يرولو دپاره پاڅى نو خلق به د غرونو په غارونو کښې پټيږى او په زمکه کښې به په سوړو کښې پټيږى، د دې دپاره چې د مالِک خُدائ د دهشت او جلال نه وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16598, 'Isaiah 2:22', 'Isaiah', 2, 22, '&nbsp;په انسان باندې توکل مۀ کوه، د هغوئ ژوند د يوې لحظې دے او د هغې قدر څۀ دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16599, 'Isaiah 3:1', 'Isaiah', 3, 1, '&nbsp;مالِک خُدائ، ربُ الافواج به د يروشلم او يهوداه نه هغه هر څۀ لرې کړى چې په هغې پورې د خلقو ژوند تړلے دے. هغه به د هغوئ نه خوراک او د څښلو اوبۀ واخلى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16600, 'Isaiah 3:2', 'Isaiah', 3, 2, '&nbsp;د هغوئ نه به باتوران او فوجيان، قاضيان او پېغمبران، فالګران او مشران،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');